(3205387, 449968, 46314, '<td valign="top">Not quite sure if I get the link to the title (I have a fair idea), but either way it''s a great shot of hands. Excellent focus, DOF - sharp as a tack on the important bits. And the tones are well exposed too - nice range from light to dark. Well done.</td>', 'Not quite sure if I get the link to the title (I have a fair idea), but either way it''s a great shot of hands. Excellent focus, DOF - sharp as a tack on the important bits. And the tones are well exposed too - nice range from light to dark. Well done.', '2007-01-10 09:50:43.000000', NULL, 1),
(3205395, 450558, 24454, '<td valign="top">What an AWESOME sentiment!  Wow!  And beautifully BEAUTIFULLY done!  I love the angle.  I love everything about this.  Good Luck!</td>', 'What an AWESOME sentiment!  Wow!  And beautifully BEAUTIFULLY done!  I love the angle.  I love everything about this.  Good Luck!', '2007-01-10 09:52:07.000000', NULL, 1),
(3205403, 447636, 46314, '<td valign="top">Nice clean lines, and well composed. I also like the tones, leaving the subject almost in silhouette, but with just enough detail to give him depth and show the walking. A bit of noise and banding detracts a bit from the sky, but other than that minor issue, it''s a great photo.</td>', 'Nice clean lines, and well composed. I also like the tones, leaving the subject almost in silhouette, but with just enough detail to give him depth and show the walking. A bit of noise and banding detracts a bit from the sky, but other than that minor issue, it''s a great photo.', '2007-01-10 09:52:37.000000', NULL, 1),
(3205409, 450850, 46314, '<td valign="top">Interesting colours coming out of this shot. Somehow the composition doesn''t feel quite right for it though. Maybe a square-on angle would have given the heavy door more weight. Or maybe it''s just that patch of white (snow?) at the bottom that is bothering me. Still, it''s a nice representation of the title.</td>', 'Interesting colours coming out of this shot. Somehow the composition doesn''t feel quite right for it though. Maybe a square-on angle would have given the heavy door more weight. Or maybe it''s just that patch of white (snow?) at the bottom that is bothering me. Still, it''s a nice representation of the title.', '2007-01-10 09:54:26.000000', NULL, 1),
(3205431, 449342, 30049, '<td valign="top">Simple, emotive, nice use of lines - and (hooray) you didn''t go overboard with color saturation.  Good luck in the challenge.</td>', 'Simple, emotive, nice use of lines - and (hooray) you didn''t go overboard with color saturation.  Good luck in the challenge.', '2007-01-10 09:57:56.000000', NULL, 1),
(3205434, 449719, 46314, '<td valign="top">There was another almost identical shot that came out a bit better than this one, simply because it had leading lines moving the viewers eye as if they were ''walking away'' with the subject. If you''d been able to compose the shot with similar leading lines, it might have improved the pic. However, the colours in your pic are fabulous and the silhouette is strongly composed. Nice shot.</td>', 'There was another almost identical shot that came out a bit better than this one, simply because it had leading lines moving the viewers eye as if they were ''walking away'' with the subject. If you''d been able to compose the shot with similar leading lines, it might have improved the pic. However, the colours in your pic are fabulous and the silhouette is strongly composed. Nice shot.', '2007-01-10 09:58:40.000000', NULL, 1),
(3205447, 450474, 30049, '<td valign="top">Annoyed might be a better description.  :D  Cute pic.</td>', 'Annoyed might be a better description.  :D  Cute pic.', '2007-01-10 10:03:13.000000', NULL, 1),
(3205451, 450128, 30049, '<td valign="top">Cool location for this shot.  The sky and background cooperated, your model (is it you?) unfortunately moved.</td>', 'Cool location for this shot.  The sky and background cooperated, your model (is it you?) unfortunately moved.', '2007-01-10 10:04:52.000000', NULL, 1),
(3205463, 449449, 65779, '<td valign="top">I like the lighting but in terms of focus, very little of this pic is in focus</td>', 'I like the lighting but in terms of focus, very little of this pic is in focus', '2007-01-10 10:06:52.000000', NULL, 1),
(3205471, 450550, 23484, '<td valign="top">Very nice shot. Meet the challenge very well. The light in the tent really adds to it. 7</td>', 'Very nice shot. Meet the challenge very well. The light in the tent really adds to it. 7', '2007-01-10 10:08:43.000000', NULL, 1),
(3205473, 448671, 46314, '<td valign="top">The person walking away is so small and so dark that the casual viewer might easily overlook it, and without that, the picture doesn''t really convey the title well. Also, many elements of the composition are distracting, rather than interesting.</td>', 'The person walking away is so small and so dark that the casual viewer might easily overlook it, and without that, the picture doesn''t really convey the title well. Also, many elements of the composition are distracting, rather than interesting.', '2007-01-10 10:09:16.000000', NULL, 1),
(3205478, 450854, 43774, '<td valign="top">I don''t see this song title in the list.</td>', 'I don''t see this song title in the list.', '2007-01-10 10:10:01.000000', NULL, 1),
(3205481, 450600, 23484, '<td valign="top">Good job. This is nice in B&amp;W but I think this would look good in color with a grungy background. 7</td>', 'Good job. This is nice in B&W but I think this would look good in color with a grungy background. 7', '2007-01-10 10:10:25.000000', NULL, 1),
(3205484, 450243, 43774, '<td valign="top">I don''t see this song title in the list.</td>', 'I don''t see this song title in the list.', '2007-01-10 10:11:41.000000', NULL, 1),
(3205485, 449192, 46314, '<td valign="top">Nice idea. Composition is a bit cluttered though (pink arm is distracting) and it has a bit of a snapshot feel. Also, I think you used a high ISO for the indoor lighting - be careful of that, it creates a lot of noise in your pic. Although in this case I think it helped the pic a bit - it lessened that cheap snapshot feel of the pic.</td>', 'Nice idea. Composition is a bit cluttered though (pink arm is distracting) and it has a bit of a snapshot feel. Also, I think you used a high ISO for the indoor lighting - be careful of that, it creates a lot of noise in your pic. Although in this case I think it helped the pic a bit - it lessened that cheap snapshot feel of the pic.', '2007-01-10 10:11:44.000000', NULL, 1),
(3205488, 450751, 43774, '<td valign="top">I don''t see this title in the list of songs</td>', 'I don''t see this title in the list of songs', '2007-01-10 10:12:31.000000', NULL, 1),
(3205495, 450462, 23484, '<td valign="top">Really cool shot. I like the darkness. 8</td>', 'Really cool shot. I like the darkness. 8', '2007-01-10 10:13:45.000000', NULL, 1),
(3205501, 450848, 46314, '<td valign="top">Clever idea - the angel is unconventional. The way the skin fades into the white background is almost ethereal - just like an angel should be. However, apart from the post-processing for red colour, the lips don''t quite grab the viewer as much as I would like them to, to support the title of the shot. Still, well taken.</td>', 'Clever idea - the angel is unconventional. The way the skin fades into the white background is almost ethereal - just like an angel should be. However, apart from the post-processing for red colour, the lips don''t quite grab the viewer as much as I would like them to, to support the title of the shot. Still, well taken.', '2007-01-10 10:15:01.000000', NULL, 1),
(3205507, 449719, 7628, '<td valign="top">What a tremendous composition - the person right on the thirds line, the striking diagonals from the mountain to the horizon and in the sweep of the clouds... but the image is so dark and lackng in contrast... I couldn''t resist trying to brighten it up.  I used levels, curves, selective colors, shadows and highlights:<br/><a href="//www.dpchallenge.com/image.php?IMAGE_ID=451043" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/7628/thumb/451043.jpg'', strrpos(''//images.dpchallenge.com/images_portfolio/7628/thumb/451043.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/7628/thumb/451043.jpg"/></a></td>', 'What a tremendous composition - the person right on the thirds line, the striking diagonals from the mountain to the horizon and in the sweep of the clouds... but the image is so dark and lackng in contrast... I couldn''t resist trying to brighten it up.  I used levels, curves, selective colors, shadows and highlights:', '2007-01-10 10:16:24.000000', NULL, 1),
(3205527, 450848, 15711, '<td valign="top">Fun high contrast.  I wonder how this will be received  by the typical DPCer. Good luck.</td>', 'Fun high contrast.  I wonder how this will be received  by the typical DPCer. Good luck.', '2007-01-10 10:18:38.000000', NULL, 1),
(3205528, 447886, 46314, '<td valign="top">Nice colour, focus and clarity. Somehow it feels as if the composition could have been stronger though. Perhaps it''s how the diagonals (land and parachute) follow each other, rather than opposing each other, which might have been more dramatic.</td>', 'Nice colour, focus and clarity. Somehow it feels as if the composition could have been stronger though. Perhaps it''s how the diagonals (land and parachute) follow each other, rather than opposing each other, which might have been more dramatic.', '2007-01-10 10:18:41.000000', NULL, 1),
(3205530, 448914, 43774, '<td valign="top">I don''t see this title in the list of songs you had to choose from</td>', 'I don''t see this title in the list of songs you had to choose from', '2007-01-10 10:18:55.000000', NULL, 1),
(3205534, 447061, 43774, '<td valign="top">I don''t see this title in the list of songs you had to choose from</td>', 'I don''t see this title in the list of songs you had to choose from', '2007-01-10 10:19:19.000000', NULL, 1),
(3205537, 450868, 46314, '<td valign="top">Interesting way to portray a difficult title. Nicely taken too.</td>', 'Interesting way to portray a difficult title. Nicely taken too.', '2007-01-10 10:19:34.000000', NULL, 1),
(3205543, 448811, 43774, '<td valign="top">I don''t see this title in the list of songs you had to choose from</td>', 'I don''t see this title in the list of songs you had to choose from', '2007-01-10 10:20:48.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3205547, 450584, 43774, '<td valign="top">I don''t see this title in the list of songs you had to choose from</td>', 'I don''t see this title in the list of songs you had to choose from', '2007-01-10 10:21:12.000000', NULL, 1),
