INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3217803, 450020, 71268, '<td valign="top">Good entry.</td>', 'Good entry.', '2007-01-12 09:12:45.000000', NULL, 1),
(3217809, 449604, 71268, '<td valign="top">Like the simplicity.</td>', 'Like the simplicity.', '2007-01-12 09:13:13.000000', NULL, 1),
(3217812, 450589, 71268, '<td valign="top">Good dynamic feel .. like it.</td>', 'Good dynamic feel .. like it.', '2007-01-12 09:13:37.000000', NULL, 1),
(3217818, 450460, 71268, '<td valign="top">Lovely</td>', 'Lovely', '2007-01-12 09:13:55.000000', NULL, 1),
(3217819, 450839, 71268, '<td valign="top">Great entry, like it a lot.</td>', 'Great entry, like it a lot.', '2007-01-12 09:13:58.000000', NULL, 1),
(3217839, 450836, 30049, '<td valign="top">I love the image at first glance for the very nice use of minimalism and the use of leading lines.  In addition, this composition does a nice job of using the rule of thirds in the placement of the trees, plaza area, and road. Good eye to see and capture this photo.  Couple of issues I have that are holding this back are 1) sizing - use the maximum 640, ALWAYS!  Show off the details. 2) Not very sharp, it''s a bit soft - perhaps from hand holding rather than a tripod?  The shutter speed had to have been fairly high to catch the leg in motion...<br/> <br/>All JMO of course.  :)  Best of luck to you in the challenge.</td>', 'I love the image at first glance for the very nice use of minimalism and the use of leading lines.  In addition, this composition does a nice job of using the rule of thirds in the placement of the trees, plaza area, and road. Good eye to see and capture this photo.  Couple of issues I have that are holding this back are 1) sizing - use the maximum 640, ALWAYS!  Show off the details. 2) Not very sharp, it''s a bit soft - perhaps from hand holding rather than a tripod?  The shutter speed had to have been fairly high to catch the leg in motion... All JMO of course.  :)  Best of luck to you in the challenge.', '2007-01-12 09:16:28.000000', NULL, 1),
(3217863, 449737, 30049, '<td valign="top">Very frosty indeed!  I love the wind-blown snow on the leftmost branch.  Looks like you could have a little sharper detail (snow crystals) but it''s not far off the mark.  The background has a bluish cast, which actually works ok to portray the cold, not sure about the haziness, thinking that it might be nice to have reduced that a little with a UV filter.  JMO of course.  :)  Overall, a splendid image.  Well done!</td>', 'Very frosty indeed!  I love the wind-blown snow on the leftmost branch.  Looks like you could have a little sharper detail (snow crystals) but it''s not far off the mark.  The background has a bluish cast, which actually works ok to portray the cold, not sure about the haziness, thinking that it might be nice to have reduced that a little with a UV filter.  JMO of course.  :)  Overall, a splendid image.  Well done!', '2007-01-12 09:19:23.000000', NULL, 1),
(3217978, 449925, 66799, '<td valign="top">I donow what over your head but it''s iteresting try</td>', 'I donow what over your head but it''s iteresting try', '2007-01-12 09:34:22.000000', NULL, 1),
