(3217989, 447653, 66799, '<td valign="top">interesting pattern</td>', 'interesting pattern', '2007-01-12 09:36:59.000000', NULL, 1),
(3218194, 448914, 32345, '<td valign="top">This is a good picture but it DNMC, this is not a song in the Top 50 as per the challenge description.</td>', 'This is a good picture but it DNMC, this is not a song in the Top 50 as per the challenge description.', '2007-01-12 10:13:43.000000', NULL, 1),
(3218212, 450591, 32345, '<td valign="top">DNMC, this is not a title in the Top 50 as per the challenge description.</td>', 'DNMC, this is not a title in the Top 50 as per the challenge description.', '2007-01-12 10:17:37.000000', NULL, 1),
(3218225, 449346, 30049, '<td valign="top">This is a wonderful idea for a still life photo.  Natural lighting is nice and the composition overall is fine.  Biggest factor in scoring impact is that the image isn''t that well focused.  Seems a little blurry.  One other thing is some fill light (bounced light from a white poster board would work great with that natural light) would help in the lower left of this image.<br/> <br/>All JMO of course.  :D  Good luck in the challenge.</td>', 'This is a wonderful idea for a still life photo.  Natural lighting is nice and the composition overall is fine.  Biggest factor in scoring impact is that the image isn''t that well focused.  Seems a little blurry.  One other thing is some fill light (bounced light from a white poster board would work great with that natural light) would help in the lower left of this image. All JMO of course.  :D  Good luck in the challenge.', '2007-01-12 10:19:34.000000', NULL, 1),
(3218231, 450243, 32345, '<td valign="top">DNMC, this is not a title in the Top 50 as per the challenge description.</td>', 'DNMC, this is not a title in the Top 50 as per the challenge description.', '2007-01-12 10:21:17.000000', NULL, 1),
