(3235772, 450731, 43775, '<td valign="top">Great capture.  I hope to someday be able to capture action shots this good.</td>', 'Great capture.  I hope to someday be able to capture action shots this good.', '2007-01-15 16:30:53.000000', NULL, 1),
(3235777, 450828, 43775, '<td valign="top">Nice colors</td>', 'Nice colors', '2007-01-15 16:33:51.000000', NULL, 1),
(3236133, 450463, 47852, '<td valign="top">Perfect title to match the photo.  Poor thing though, that''s got to be uncomfortable.</td>', 'Perfect title to match the photo.  Poor thing though, that''s got to be uncomfortable.', '2007-01-15 17:50:36.000000', NULL, 1),
(3236252, 450827, 40370, '<td valign="top">Love the flames.</td>', 'Love the flames.', '2007-01-15 18:21:30.000000', NULL, 1),
(3236269, 450731, 40370, '<td valign="top">Nice, good practice for upcoming motion panning, I shot some pics of my kid sledding the past two weekends but don''t think I have anything close to your great subject clarity.</td>', 'Nice, good practice for upcoming motion panning, I shot some pics of my kid sledding the past two weekends but don''t think I have anything close to your great subject clarity.', '2007-01-15 18:25:31.000000', NULL, 1),
(3236301, 450428, 40370, '<td valign="top">Beautiful color and lighting, I like the thin white border where it intersects the colors but not so much at the top on the brown, maybe because it''s such a tight crop up there. 7</td>', 'Beautiful color and lighting, I like the thin white border where it intersects the colors but not so much at the top on the brown, maybe because it''s such a tight crop up there. 7', '2007-01-15 18:33:07.000000', NULL, 1),
(3236325, 449719, 40370, '<td valign="top">Nice waves in the sky. Complimentary coloring too.</td>', 'Nice waves in the sky. Complimentary coloring too.', '2007-01-15 18:37:39.000000', NULL, 1),
(3236342, 449898, 40370, '<td valign="top">Love the reflective quality, sets this image apart from the average. Don''t mind the hot sugar or mug lines, but the hot spot on the spoon is harsh.</td>', 'Love the reflective quality, sets this image apart from the average. Don''t mind the hot sugar or mug lines, but the hot spot on the spoon is harsh.', '2007-01-15 18:39:41.000000', NULL, 1),
(3236351, 450550, 40370, '<td valign="top">Fabulous, this could be the cover page for an REI (any outdoor gear actually) catalog, nicely done. 8</td>', 'Fabulous, this could be the cover page for an REI (any outdoor gear actually) catalog, nicely done. 8', '2007-01-15 18:41:13.000000', NULL, 1),
(3236371, 449684, 40370, '<td valign="top">Great update to an old idea. I really like the blue coloring but find the reflection a slight distraction from the subject. Nice composition also.</td>', 'Great update to an old idea. I really like the blue coloring but find the reflection a slight distraction from the subject. Nice composition also.', '2007-01-15 18:43:50.000000', NULL, 1),
(3236385, 447644, 40370, '<td valign="top">Great portrait, love the ruffled shirt, the "not quite put together look".</td>', 'Great portrait, love the ruffled shirt, the "not quite put together look".', '2007-01-15 18:46:10.000000', NULL, 1),
(3236401, 450844, 40370, '<td valign="top">Harsh processing for a harsh ending, fits the image. It would be nice to see a bit more of a face to identify with.</td>', 'Harsh processing for a harsh ending, fits the image. It would be nice to see a bit more of a face to identify with.', '2007-01-15 18:48:18.000000', NULL, 1),
(3236422, 449670, 40370, '<td valign="top">The flame is not necessarily the subject here but rather what''s burning. Interesting.</td>', 'The flame is not necessarily the subject here but rather what''s burning. Interesting.', '2007-01-15 18:51:12.000000', NULL, 1),
(3236444, 449410, 40370, '<td valign="top">This is a tough one for me cause I love to take pics of flowers outside, real ones "in the ground - growing", NOT in a studio ... HOWEVER ... they just don''t do well on DPC unless maybe it''s a "flower" challenge ( and the studio ones will still win). You''ve got great focus on your subject but just too much background to make this stand-out in a "Song Title" challenge. 5</td>', 'This is a tough one for me cause I love to take pics of flowers outside, real ones "in the ground - growing", NOT in a studio ... HOWEVER ... they just don''t do well on DPC unless maybe it''s a "flower" challenge ( and the studio ones will still win). You''ve got great focus on your subject but just too much background to make this stand-out in a "Song Title" challenge. 5', '2007-01-15 18:56:15.000000', NULL, 1),
(3236451, 448696, 40370, '<td valign="top">Very crisp for a misty landscape, last bit of sunlight is beautiful. I''d tilt your horizon line a degree or so clockwise to center the reflection line.</td>', 'Very crisp for a misty landscape, last bit of sunlight is beautiful. I''d tilt your horizon line a degree or so clockwise to center the reflection line.', '2007-01-15 18:58:34.000000', NULL, 1),
(3236465, 448191, 40370, '<td valign="top">He should have more money in front of him ... cause now he''s broke and in LUV ??</td>', 'He should have more money in front of him ... cause now he''s broke and in LUV ??', '2007-01-15 19:00:18.000000', NULL, 1),
(3236472, 447093, 40370, '<td valign="top">James Bond "Moonraker" ... no wait ... that was a while ago. Very cool "far away" depiction.</td>', 'James Bond "Moonraker" ... no wait ... that was a while ago. Very cool "far away" depiction.', '2007-01-15 19:01:49.000000', NULL, 1),
(3236510, 449192, 40370, '<td valign="top">This looks too real to be staged. Best wishes for this little one.</td>', 'This looks too real to be staged. Best wishes for this little one.', '2007-01-15 19:09:53.000000', NULL, 1),
