(3240496, 447061, 53572, '<td valign="top">this is an interesting idea, but it could be improved in a few ways. the main probelm is the size and resolution of the image.  i realise this may be unavoidable, depending on the equipment you hav to work with, but if you bumped up the resolution in your camera, this would greatly improve the shot.<br/> <br/>the rest of what i''m going to say is really hypothetical, if the resolution were better.croppig closer to the woman, so bring the viewrs gazemore immediately to her would certainly help, as at the moment she is rather lost in the background.  <br/> <br/>so a good start, and keep shooting!</td>', 'this is an interesting idea, but it could be improved in a few ways. the main probelm is the size and resolution of the image.  i realise this may be unavoidable, depending on the equipment you hav to work with, but if you bumped up the resolution in your camera, this would greatly improve the shot. the rest of what i''m going to say is really hypothetical, if the resolution were better.croppig closer to the woman, so bring the viewrs gazemore immediately to her would certainly help, as at the moment she is rather lost in the background.   so a good start, and keep shooting!', '2007-01-16 13:54:04.000000', NULL, 1),
(3240555, 450229, 53572, '<td valign="top">in interesting idea, and the beginnings of a very nice image, with interesting symbolism.<br/> <br/>however, the set up makes it very hard to read the image.  the small silver object on the left is very hard to read - a diamond ring?  a pencil sharpener?  if this were shot from a higher angle, with all the objects closer to each other, it would make a more dramatic composition.<br/> <br/>the flash is also very harsh, creating a very bright foreground where there is nothing happening. ambient light, while somewhat harder to shoot in, probably would create a more pleasing result here.  even filtering the flash with a piece of white paper would soften the effect, and make a gentler light.<br/> <br/>so, a good start, and keep shooting!</td>', 'in interesting idea, and the beginnings of a very nice image, with interesting symbolism. however, the set up makes it very hard to read the image.  the small silver object on the left is very hard to read - a diamond ring?  a pencil sharpener?  if this were shot from a higher angle, with all the objects closer to each other, it would make a more dramatic composition. the flash is also very harsh, creating a very bright foreground where there is nothing happening. ambient light, while somewhat harder to shoot in, probably would create a more pleasing result here.  even filtering the flash with a piece of white paper would soften the effect, and make a gentler light. so, a good start, and keep shooting!', '2007-01-16 14:08:33.000000', NULL, 1),
(3240577, 450839, 30861, '<td valign="top">Oh, simply outstanding woody work! Good luck with it! Bumping. Go for the gold!</td>', 'Oh, simply outstanding woody work! Good luck with it! Bumping. Go for the gold!', '2007-01-16 14:14:39.000000', NULL, 1),
(3240578, 450796, 30861, '<td valign="top">This is outstanding, if somewhat macabre. It will test the voters'' tolerance for the metaphorical or symbolic. How many will see the heart torn out, the voice silenced?  Good luck to you. I''m in a similar boat (the metaphorical boat) and am scoring well so far (knock on wood) so good luck to us :-)</td>', 'This is outstanding, if somewhat macabre. It will test the voters'' tolerance for the metaphorical or symbolic. How many will see the heart torn out, the voice silenced?  Good luck to you. I''m in a similar boat (the metaphorical boat) and am scoring well so far (knock on wood) so good luck to us :-)', '2007-01-16 14:14:47.000000', NULL, 1),
(3240581, 449925, 30861, '<td valign="top">This is way cool :-) I''m a little uneasy with your choice of super-tight crop on top, but sobeit.</td>', 'This is way cool :-) I''m a little uneasy with your choice of super-tight crop on top, but sobeit.', '2007-01-16 14:15:37.000000', NULL, 1),
(3240590, 450442, 30861, '<td valign="top">This is quite compelling. I am back to bump it. I fear it''s not WOW enough for the usual crowd, but in my book it''s very tautly put together and extraordinarily metaphorical. It would display to great advantage as a large print I imagine. Love the truncated foreground and right edge figures.</td>', 'This is quite compelling. I am back to bump it. I fear it''s not WOW enough for the usual crowd, but in my book it''s very tautly put together and extraordinarily metaphorical. It would display to great advantage as a large print I imagine. Love the truncated foreground and right edge figures.', '2007-01-16 14:18:21.000000', NULL, 1),
(3240592, 449976, 30861, '<td valign="top">Excellent! Beautifully moody, really intense.</td>', 'Excellent! Beautifully moody, really intense.', '2007-01-16 14:18:55.000000', NULL, 1),
(3240598, 450550, 30861, '<td valign="top">Outstanding. By far the most evocative of the "Far Away" entries I have seen so far. I am returning to this and am still troubled by the slightly off-level horizon, but no matter. Beautiful gradient, wonderful star :-)</td>', 'Outstanding. By far the most evocative of the "Far Away" entries I have seen so far. I am returning to this and am still troubled by the slightly off-level horizon, but no matter. Beautiful gradient, wonderful star :-)', '2007-01-16 14:20:26.000000', NULL, 1),
(3240721, 448311, 67007, '<td valign="top">welll..... some other angle might do the difference, like showing the face.</td>', 'welll..... some other angle might do the difference, like showing the face.', '2007-01-16 14:58:43.000000', NULL, 1),
(3240758, 450648, 67007, '<td valign="top">Eitthvað kannast maður við þessa :) Svakalega flott mynd og verðskuldar alveg tíuna hjá mér.</td>', 'Eitthvað kannast maður við þessa :) Svakalega flott mynd og verðskuldar alveg tíuna hjá mér.', '2007-01-16 15:11:07.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3240763, 448696, 67007, '<td valign="top">Brilliant</td>', 'Brilliant', '2007-01-16 15:12:45.000000', NULL, 1),
(3240918, 449815, 53572, '<td valign="top">a very funny interpretation of the title!  the composition is quite good, although the go-cart wheels (?) are a little distracting.  however, when shooting candids like this, we can''t always choose our foregrounds.<br/> <br/>however, i think this image could have been gretly improved with different processing.  this is an advanced challenge, so you could have been much more flexible with the PP.<br/> <br/>the flash light is very harsh, so a masked multiply layer to tone that down might have helped there, and i think converting this to b/w would have helped focus our eyes on the action.<br/> <br/>a good start indeed, and keep shooting!</td>', 'a very funny interpretation of the title!  the composition is quite good, although the go-cart wheels (?) are a little distracting.  however, when shooting candids like this, we can''t always choose our foregrounds. however, i think this image could have been gretly improved with different processing.  this is an advanced challenge, so you could have been much more flexible with the PP. the flash light is very harsh, so a masked multiply layer to tone that down might have helped there, and i think converting this to b/w would have helped focus our eyes on the action. a good start indeed, and keep shooting!', '2007-01-16 15:56:36.000000', NULL, 1),
